package conciliummodern;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.level.Level;
import net.minecraft.world.phys.Vec3;
import net.minecraftforge.network.*;
/** Cosmetic only; the original packet's h is arc height, not line width. */
public final class ConciliumArcNetwork {
 private static final net.minecraftforge.network.simple.SimpleChannel NETWORK=NetworkRegistry.newSimpleChannel(ResourceLocation.parse("thaumicconcilium:arc_fx"),()->"2","2"::equals,"2"::equals);
 public record Arc(ResourceLocation dimension,Vec3 from,Vec3 to,int color,float height){}
 public record Blood(ResourceLocation dimension,Vec3 at){}
 public record Taint(ResourceLocation dimension,Vec3 at){}
 public record Bolt(ResourceLocation dimension,int caster,Vec3 target,int color){}
 public static void init(){NETWORK.messageBuilder(Arc.class,0,NetworkDirection.PLAY_TO_CLIENT).encoder((p,b)->{b.writeResourceLocation(p.dimension);b.writeDouble(p.from.x);b.writeDouble(p.from.y);b.writeDouble(p.from.z);b.writeDouble(p.to.x);b.writeDouble(p.to.y);b.writeDouble(p.to.z);b.writeInt(p.color);b.writeFloat(p.height);}).decoder(b->new Arc(b.readResourceLocation(),new Vec3(b.readDouble(),b.readDouble(),b.readDouble()),new Vec3(b.readDouble(),b.readDouble(),b.readDouble()),b.readInt(),b.readFloat())).consumerMainThread((packet,context)->{var connection=context.get().getNetworkManager();net.minecraftforge.fml.DistExecutor.unsafeRunWhenOn(net.minecraftforge.api.distmarker.Dist.CLIENT,()->()->RemainingMobsClient.arc(packet,connection));context.get().setPacketHandled(true);}).add();
 NETWORK.messageBuilder(Blood.class,1,NetworkDirection.PLAY_TO_CLIENT).encoder((p,b)->{b.writeResourceLocation(p.dimension);b.writeDouble(p.at.x);b.writeDouble(p.at.y);b.writeDouble(p.at.z);}).decoder(b->new Blood(b.readResourceLocation(),new Vec3(b.readDouble(),b.readDouble(),b.readDouble()))).consumerMainThread((packet,context)->{var connection=context.get().getNetworkManager();net.minecraftforge.fml.DistExecutor.unsafeRunWhenOn(net.minecraftforge.api.distmarker.Dist.CLIENT,()->()->RemainingMobsClient.blood(packet,connection));context.get().setPacketHandled(true);}).add();
 NETWORK.messageBuilder(Taint.class,2,NetworkDirection.PLAY_TO_CLIENT).encoder((p,b)->{b.writeResourceLocation(p.dimension);b.writeDouble(p.at.x);b.writeDouble(p.at.y);b.writeDouble(p.at.z);}).decoder(b->new Taint(b.readResourceLocation(),new Vec3(b.readDouble(),b.readDouble(),b.readDouble()))).consumerMainThread((packet,context)->{var connection=context.get().getNetworkManager();net.minecraftforge.fml.DistExecutor.unsafeRunWhenOn(net.minecraftforge.api.distmarker.Dist.CLIENT,()->()->ConciliumParticleEffects.taint(packet,connection));context.get().setPacketHandled(true);}).add();
 NETWORK.messageBuilder(Bolt.class,3,NetworkDirection.PLAY_TO_CLIENT).encoder((p,b)->{b.writeResourceLocation(p.dimension);b.writeVarInt(p.caster);b.writeDouble(p.target.x);b.writeDouble(p.target.y);b.writeDouble(p.target.z);b.writeInt(p.color);}).decoder(b->new Bolt(b.readResourceLocation(),b.readVarInt(),new Vec3(b.readDouble(),b.readDouble(),b.readDouble()),b.readInt())).consumerMainThread((packet,context)->{var connection=context.get().getNetworkManager();net.minecraftforge.fml.DistExecutor.unsafeRunWhenOn(net.minecraftforge.api.distmarker.Dist.CLIENT,()->()->ConciliumParticleEffects.bolt(packet,connection));context.get().setPacketHandled(true);}).add();}
 public static void emit(Level level,Vec3 from,Vec3 to,int color,float height){if(level.isClientSide)return;NETWORK.send(PacketDistributor.NEAR.with(()->new PacketDistributor.TargetPoint(from.x,from.y,from.z,32,level.dimension())),new Arc(level.dimension().location(),from,to,color,height));}
 public static void blood(Level level,Vec3 at){if(level.isClientSide)return;NETWORK.send(PacketDistributor.NEAR.with(()->new PacketDistributor.TargetPoint(at.x,at.y,at.z,32,level.dimension())),new Blood(level.dimension().location(),at));}
 public static void taint(Level level,Vec3 at){if(level.isClientSide)return;NETWORK.send(PacketDistributor.NEAR.with(()->new PacketDistributor.TargetPoint(at.x,at.y,at.z,32,level.dimension())),new Taint(level.dimension().location(),at));}
 public static void bolt(net.minecraft.world.entity.LivingEntity caster,Vec3 target,int color){var level=caster.level();if(level.isClientSide)return;NETWORK.send(PacketDistributor.NEAR.with(()->new PacketDistributor.TargetPoint(caster.getX(),caster.getY(),caster.getZ(),32,level.dimension())),new Bolt(level.dimension().location(),caster.getId(),target,color));}
}
